INSERT INTO `mod_lore_codex_entry` (`ID`, `Kind`, `Zone`, `SortOrder`, `Faction`, `RequiredState`, `Title`, `Body`, `Sources`) VALUES
(49000, 0, 490, 0, 0, 0, 'Un''Goro Crater', 'Un''Goro Crater is a vast sunken jungle in southern Kalimdor, ringed by cliffs, with the deserts of Tanaris to the east and the wastes of Silithus beyond its northwestern ridge. Steam rises from its pools, and at its heart the volcano of Fire Plume Ridge still smolders. Visitors say that entering it is like stepping into another world. The crater seems untouched by outside hands, and its creatures are nobler, mightier kin of beasts known elsewhere: devilsaurs and stegodons crash through the trees, ravasaurs hunt the marshes, pterrordax wheel overhead and great apes rule the northeast. Even the plants fight back, for the bloodpetals walk and lash at travelers. Stranger things lie hidden. Colored power crystals glitter across the basin, and crystal pylons of legend stand in remote corners. In the south the Gorishi silithid have dug a hive, and scholars wonder whether the silithid draw their strength from here. Most visitors shelter at Marshal''s Refuge, a camp of stranded explorers in the north.', 'quest 4294 description (lush, untainted by outside hands, explorers just discovering its secrets); quest 4289 description (nobler versions of creatures, cries of the Earth Mother); quest 4287 reward text (like a completely different world); quest 1124 description (Silithus west of Un''Goro via the northwestern ridge); quest 4493 reward text (Un''Goro west of Gadgetzan; Gracina''s theory); quest 4502 description (volcanic activity in the middle of the crater); quests 4141, 4145 (bloodpetals); quest 3881 description; zone_areas: devilsaur, stegodon, ravasaur, pterrordax, gorilla, Gorishi spawns; power crystal objects; Shaper''s Terrace 4382 and Waygate 4381; warcraft.wiki.gg/wiki/Un''Goro_Crater; warcraft.wiki.gg/wiki/Shaper''s_Terrace (WotLK northern terrace, titan-related, builder not stated)'),
(49001, 1, 490, 1, 0, 0, 'Marshal''s Refuge', 'Marshal''s Refuge is a camp on high ground at the northern edge of the crater, where Marshal Expeditions fled when the beasts overran its base camps. It has become a home for the lost and stranded, where some arrive with a purpose and others by accident. A gnome with no memory lingers among the tents, two travelers who refuse to speak to each other sulk amid scurrying bloodpetal pests, and a castaway named Shizzle, too frightened of gryphons to fly home, builds a flying machine. J.D. Collie studies crystals in a nearby cave, the kodo Dadanga hopes for a snack of bloodpetal sprouts, and Gadgetzan bruisers guard the town''s interests. Words written on a stone warn simply: beware of pterrordax.', 'zone_areas area 541: Williden 9270, Hol''anyee 9271, Spark 9272, Petra Grossen 9273, Dadanga 9274, Linken 8737, Larion 9118, Muigin 9119, Spraggle 9997, Shizzle 9998, Quixxil 10977, Gryfe 10583, Gadgetzan Bruiser 9460, Beware of Pterrordax 174682; quest 3884 description (sought higher ground once their base camps were overrun); npc_text 3546 (Spraggle: some come here with a purpose, others by accident); quest 4503 description (Shizzle); quest 3941 description (J.D. in the cave); npc_text 3793, quest 5150 (Dadanga and bloodpetal sprouts); npc_text 9774 (Gadgetzan Bruiser); quest 4501 completion text; warcraft.wiki.gg/wiki/Marshal_Expeditions (Dadanga a kodo); warcraft.wiki.gg/wiki/Dadanga (kodo); zone_areas area 541: Bloodpetal Pest 9157 x4'),
(49002, 1, 490, 2, 0, 0, 'Lakkari Tar Pits', 'Just south of Marshal''s Refuge lie the Lakkari Tar Pits, black pools of sticky tar. Creatures of living tar drag themselves out of the muck, from creepers and lurkers to hulking tar lords, while bloodpetal flayers root along the banks and pterrordax circle above. Tran''rek, a schemer in Gadgetzan, wants the tar these beasts carry rather than ordinary pitch, sure that the chlorophyll in their skin makes it uncommonly sticky. Near the pits stands the Northern Crystal Pylon, one of the three great pylons the crater''s few residents whisper about. Here too, close to the refuge, the dwarf engineer Karna Remtravel has pitched her camp to marvel at the crater''s wonders.', 'zone_areas area 538: Tar Beast, Tar Creeper, Tar Lurker, Tar Lord, Bloodpetal Flayer, Thresher, Pterrordax; Northern Crystal Pylon 164955; Karna Remtravel 9618; quest 4504 description and reward text (tar from the beasts, chlorophyll in their skin, super sticky); quest 4285 description (northern pylon fairly close); npc_text 2810 (pylons a source of legend); quest 4243 description; warcraft.wiki.gg/wiki/Lakkari_Tar_Pits (just south of Marshal''s Refuge); warcraft.wiki.gg/wiki/Karna_Remtravel (at the entrance to Marshal''s Refuge); npc_text 2734 (Karna: wonderful things here)'),
(49003, 1, 490, 3, 0, 0, 'Fungal Rock', 'East of Marshal''s Refuge, Fungal Rock is the lair of the great apes of Un''Goro, where gorillas, stompers and thunderers roam the slopes. The tauren hunter Torwa Pathfinder counts their pelts a fair test of strength, but the greater test waits in a cave at the edge of their land, home of the huge red ape he calls U''cha, in his eyes one of the Earth Mother''s greatest sons, with arms as thick as tree trunks. Here the engineer Karna Remtravel lost her mechanical ape, A-Me 01, after an alpha male rushed up to greet it. The apes seem to have accepted the machine: one big thunderer keeps her company, never straying from her side.', 'quest 4243 description (Fungal Rock, the apes'' lair, just east of here; alpha male); quest 4289 description (great apes to the north); quest 4301 description and completion text (U''cha, cave, huge and red, teeth the size of daggers, arms as thick as tree trunks); creature_text 6516 (thunderer lies down and cuddles up next to A-Me 01); quest 4243 reward text (two dents); zone_areas area 542: Un''Goro Stomper, Gorilla, Thunderer; posarea: U''cha 9622, Uhk''loc 6585 and A-Me 01 9623 stand at the edge of 542 in area 490; creature 24081 (thunderer 6516, stationary, 3.5 yards from A-Me 01 guid 24268)'),
(49004, 1, 490, 4, 0, 0, 'Fire Plume Ridge', 'Fire Plume Ridge is the smoldering volcano at the heart of the crater, south of Marshal''s Refuge. Living blazes and scorching elementals walk its burned slopes, and the lava lake at its summit is said to be hot enough to fuse thorium and bone. The inventor Krakle, camped by the Golakka springs, suspects that the volcano warms his pools and wants its hot spots measured. On the ridge dwells Blazerunner, a powerful fire elemental wrapped in an aura that the refuge''s residents say none has penetrated; many who tried to face him were pushed from the rocky paths. The explorer Ringo went to explore these slopes too, and his friend Spraggle fears he has stayed too long.', 'zone_areas area 537: Living Blaze 6521, Scorching Elemental 6520, Krakle''s Thermometer 10541 hot spots, Blazerunner 9376, Ringo 9999; quests 5801/5802 description (lava lake up top hot enough to fuse thorium and bone); quest 974 description and reward text; quest 3962 description and log text (Golden Flame in the cave); quest 4005 reward text (charred center, aura, pushed from the rocky paths); quest 4492 description (volcano south of the refuge); quest 4491 description; quest 4502 description'),
(49005, 1, 490, 5, 0, 0, 'Golakka Hot Springs', 'In the west of the crater, steaming pools and geysers make up the Golakka Hot Springs. The inventor Krakle camps on their shore, puzzling over where the heat comes from. Seeing how close the pools lie to Fire Plume Ridge, he suspects the volcano, though he is too scared of its fire elementals to take the readings himself and has built a thermometer for braver souls to carry. Pterrordax, diemetradons and stegodons come down to the water, and the Western Crystal Pylon stands nearby. A cheerful woman named Simone strolls these shores with her growling pet Precious, delighting in the beauty all around and urging everyone she meets to enjoy what life has to give.', 'quest 974 description and completion text; quest 980 description (Winterspring springs with no volcano, Donova Snowden); zone_areas area 543: Krakle 10302, Frenzied Pterrordax, Elder Diemetradon, Plated Stegodon, Western Crystal Pylon 164956, Simone the Inconspicuous 14527, Precious 14528; npc_text 7041, 7042 (Simone, Precious); creature_template 14533 Simone the Seductress, 14538 Precious the Devourer; 14528 is type demon; warcraft.wiki.gg/wiki/Golakka_Hot_Springs (western Un''Goro); warcraft.wiki.gg/wiki/Simone_the_Inconspicuous; quest 7636 (context only: hunter-only, turned in to Vartrus in Felwood, its four demons stand in four zones)'),
(49006, 1, 490, 6, 0, 0, 'Terror Run', 'Terror Run, in the southwest of the crater, earned its name honestly. Herds of stegodons, plated, spiked and thunderstomping, crash among the trees, elder diemetradons bask nearby and frenzied pterrordax wheel overhead, while a great beast called Gruff roams among them. Marshal Expeditions came here to dig for the bones of long-dead stegodons and diemetradons, only to find plenty of living ones as well, and their reluctant chief digger declared the name fantastic, and did not mean it as praise. Dinosaur bones still lie scattered across the ground, and some of the research equipment the expedition left behind when it fled can still be found here. Gorishi reavers and workers stray up from the hive to the east.', 'quest 3882 description (Terror Run, FANTASTIC name, dead and live stegodons and diemetradons); quest 3881 description (supplies left behind); zone_areas area 539: Stegodon, Plated, Spiked, Thunderstomp Stegodon, Elder Diemetradon, Frenzied Pterrordax, Gruff 6583 (rank 2), Dinosaur Bone 161527 x14, Research Equipment 161521, Gorishi Reaver, Worker; warcraft.wiki.gg/wiki/Terror_Run (southwestern Un''Goro, just west of the Slithering Scar); warcraft.wiki.gg/wiki/Gruff (rare stegodon, Terror Run)'),
(49007, 1, 490, 7, 0, 0, 'The Slithering Scar', 'The Slithering Scar is a great silithid hive gouged into the south of the crater, the home of the insects called the Gorishi. Workers, wasps, stingers, tunnelers and reavers swarm through its tunnels, and the ore in its walls comes smeared with ooze. Deep inside lie larval hatcheries hung with dangling spawn, and a brood mother called Clutchmother Zavas prowls the hive. Hol''anyee Marshal finds the Gorishi entirely alien to the ecology of Un''Goro and wants to know why they are here at all.', 'zone_areas area 540: Gorishi Reaver, Worker, Wasp, Tunneler, Stinger, Gorishi Egg, Clutchmother Zavas 6582 (rank 4), Ooze Covered Truesilver Deposit; quest 3883 description (alien to the ecology, larval hatcheries, hanging larval spawns); quest 4507 description and completion text (crystal, hive-wide attunement device, malign intelligence); quest 13903 description (Slithering Scar in the south); warcraft.wiki.gg/wiki/The_Slithering_Scar (Gorishi hive)'),
(49008, 1, 490, 8, 0, 0, 'The Marshlands', 'The Marshlands spread across the southeast of the crater, close to where the road from Tanaris comes down into the jungle. Hunters and runners stalk the reeds, venomhide ravasaurs carry a potent poison, and their nests lie scattered across the fen under the eye of a fearsome matriarch. Above them all is Lar''korwi, the dominant male whose name means sharp claw. At the southeastern edge of the marsh the ravasaur trainer Mor''vek keeps a lonely camp. The Eastern Crystal Pylon stands in these wetlands, and on the shore of a small pond lies a wrecked raft, though it is hard to see how so little water could ever have carried it.', 'zone_areas area 1942: Ravasaur, Ravasaur Hunter, Runner, Venomhide Ravasaur, Ravasaur Matriarch 6581 (rank 4), Venomhide Egg, Ravasaur Matriarch''s Nest, Mor''vek 11701, Eastern Crystal Pylon 164957, A Wrecked Raft 161505, A Small Pack 161504, Un''Goro Flat Rock 169217, Fresh Threshadon Carcass 166863; quest 9063 description (road from Tanaris enters the crater); quest 13850 description (poison blood, spit, skin); quest 4291 description (dominant male); npc_text 2835 (sharp claw); quest 3844 description (wrecked raft by a small pond); warcraft.wiki.gg/wiki/The_Marshlands (southeast, often the first area encountered); quest 3844 description (pond too small)'),
(49009, 1, 490, 9, 0, 13, 'The Shaper''s Terrace', 'High on the bluffs above Marshal''s Refuge lies the Shaper''s Terrace, a great expanse of stonework tied to the titans. Beside it stands a titan waygate that joins Un''Goro to Sholazar Basin, far away in Northrend. On the terrace looms the Etymidian, a stone colossus made by the titans, silent and inert, with an empty rune-shaped slot in its chest. It is not alone. Death''s Hand acolytes of the Cult of the Damned have taken the terrace, and their leader, High Cultist Herenn, keeps to the overlook nearby.', 'zone_areas area 4382: Death''s Hand Acolyte 28602 x10, The Etymidian 28092; area 4381 Waygate; quest 12546 description (one of the most destructive forces ever created by the titans); quest 12548 description (Waygate activated for the first time in seven centuries); quest 12561 description (Sholazar, the cradle of life); quest 12547 description (rune-shaped slot, Omega Rune inside the Shaper''s Terrace); creature_text 28601 (High Cultist Herenn); warcraft.wiki.gg/wiki/Shaper''s_Terrace (added in 3.0.2, on the bluffs above Marshal''s Refuge, Cult of the Damned, Herenn holds the Omega Rune); quest 12547 description (inactive colossus, empty rune-shaped slot, nearby overlook); creature_text 28601 (Herenn)'),
(49010, 2, 490, 1, 0, 0, 'Linken', 'Linken is a gnome who turned up in Un''Goro with no idea how he got there. He remembers traveling, and a raft, and little else. The refugees find him friendly and a little strange: unlike most gnomes he shows no interest in gadgets or experiments, and he sometimes greets people with a demand for payment before catching himself. Asked how he came to the crater, he can only say that it is a secret to everybody. All he is sure of is that he came here for something important.', 'npc_text 2633 (not sure how I got here, a raft); npc_text 2634 (Pay me and I''ll talk); quest 3908 description (it''s a secret to everybody); quest 3961 description (not interested in experiments or gadgets like most gnomes; a true warrior at heart); quest 3962 description and reward text (journey, last step, Golden Flame returned to my homeland); warcraft.wiki.gg/wiki/Linken (gnome warrior, raft crash); quest 3941 description (I know I came here for something important)'),
(49011, 2, 490, 2, 0, 0, 'J.D. Collie', 'J.D. Collie is a gnome who has made a cave at Marshal''s Refuge her home, though she cannot say how she came to the crater. She spends her days on the colored power crystals that lie all over Un''Goro, certain they hold a power everyone else ignores. Her experiments rarely go to plan. Many end in a yelp of pain and a promise that the last thirteen tries were only practice, and now and then she wonders aloud whether she should go back downstream. She admits she will believe almost anything she is told, including tales of great crystal pylons in the wilds. Linken remembers that she was kind to him when he first stumbled in.', 'npc_text 2817 (cave is my home now, can''t say how I got here, studies crystals); creature_text 9117 (OW, last 13 tries were just practice, go back downstream); quest 4284 description; quest 4285 description (call me gullible, I''ll usually believe anything); quest 3941 description (J.D. was very kind to me when I first arrived); quest 3942 description; warcraft.wiki.gg/wiki/J.D._Collie (female gnome); creature_template_model 9117 display 8478, creature_model_info Gender 1'),
(49012, 2, 490, 3, 0, 0, 'Williden and Hol''anyee Marshal', 'Williden Marshal and his sister Hol''anyee lead Marshal Expeditions, a troupe of scientists and explorers aligned with no faction who travel Azeroth in search of its wild and untamed majesty. Williden is the leader, still able to welcome a stranger warmly in the middle of disaster. Hol''anyee is the chief scientist and biologist, who holds that a setback is no reason for research to stop. Un''Goro was meant to be their greatest venture, and it has become their worst. They underestimated the savagery of the crater, lost their camps and most of what they brought, and now wait out their troubles at the refuge, while their chief digger offers his gold teeth to anyone who will carry him away.', 'npc_text 3096 (Williden: my sister, our companions, scientists and explorers); npc_text 3095 (Hol''anyee: chief scientist and biologist, my brother); quest 3881 description (non-aligned expedition troupe, latest and greatest endeavor, underestimated the savagery); quest 3883 description (setback does not stop research); quest 3884 reward text (lost like almost everything else); npc_text 3094 (Spark: gold teeth); warcraft.wiki.gg/wiki/Marshal_Expeditions'),
(49013, 2, 490, 4, 0, 0, 'Torwa Pathfinder', 'Torwa Pathfinder is a tauren hunter who camps where the road from Tanaris enters the crater. To him Un''Goro cries of the Earth Mother: its creatures seem nobler versions of the beasts of his homeland, and he thanks the spirits of every one that falls. He measures others not by race or calling but by the testing of spirit and mind against nature, and he respects any who can stand against the crater''s great beasts. The ravasaur Lar''korwi killed his brother not far from his camp. Torwa has also sought druids for a gentler purpose, a toxin of bloodcap, Gorishi stings and Un''Goro soil to calm the devilsaurs, since killing one only lets another take its territory.', 'npc_text 2816 (race and profession mean nothing, testing of spirit and mind); quest 4289 description and reward text (cries of the Earth Mother, nobler versions, thank the spirits); quest 9063 description (requested the help of a druid; road from Tanaris); quests 9052, 9051, 9053 (bloodcap, Gorishi stings, Un''Goro soil; pacify the devilsaurs; another moves into its territory); quest 4290 description (brother killed not far from this spot); warcraft.wiki.gg/wiki/Torwa_Pathfinder (tauren hunter)'),
(49014, 2, 490, 5, 0, 0, 'Karna Remtravel', 'Karna Remtravel is a dwarf engineer camped near Marshal''s Refuge who finds the crater simply amazing, though not quite as amazing as the things she can build. Like her uncle Remtravel, who loves old places, she dreams of discovering new things from lost cultures. To study the apes up close she built a mechanical ape, A-Me 01, with scrying gems for eyes so that Karna could see all she saw. A-Me reached Fungal Rock before the link failed, the last image an alpha male rushing up to say hello.', 'npc_text 2734 (amazing, engineering, uncle Remtravel loves old stuff, lost cultures); quest 4243 description and reward text; quest 4244 description and reward text (mithril casing burnt out); creature_text 9623 (A-Me good, home); quest 4245 reward text; npc_text 2735; warcraft.wiki.gg/wiki/Karna_Remtravel (dwarf, female, uncle Remtravel); creature_template_model 9618 display 8831, creature_model_info Gender 1; warcraft.wiki.gg/wiki/Karna_Remtravel'),
(49015, 2, 490, 6, 0, 0, 'Spraggle Frock and Ringo', 'Spraggle Frock greets newcomers to Marshal''s Refuge with the thought that some arrive with a purpose and some by accident, but everyone there has a story. Hers is one of fright. She never worried about the crater''s beasts until she found the words ''beware of pterrordax'' written on a large stone, and now she will not leave the refuge until someone thins their numbers. Her friend Ringo is bolder, or less careful. He set out to explore the volcano to the south and has been gone far too long, and Spraggle offers her canteen to anyone who will look for him, sure that he will need it.', 'npc_text 3546 (Spraggle gossip); quest 4501 completion and reward text; quest 4492 description; quest 4491 description; creature_text 9999 and 9997; warcraft.wiki.gg/wiki/Spraggle_Frock (female); warcraft.wiki.gg/wiki/Spraggle_Frock (female goblin)'),
(49016, 2, 490, 7, 2, 0, 'Mor''vek', 'Mor''vek is a ravasaur trainer who keeps a lonely camp at the southeastern edge of the Marshlands, not far from where the road from Tanaris enters the crater. Around him hunt the ravasaurs of Un''Goro, kin of the raptors of the Barrens, clever and volatile beasts said to keep a code of their own. Among them are the venomhides, whose bite carries a potent poison.', 'npc_text 14474; npc_text 2835 (Torwa: ravasaurs related to the raptors of the Barrens, intelligent, volatile, a code of conduct); creature_template 6508 Venomhide Ravasaur (Venomhide Poison 14792); DB: Mor''vek 11701 at map 71.2,73.7, Torwa 9619 at 71.6,75.9; creature_template 11701 subname Ravasaur Trainers, faction 126; factiontemplate_dbc 126; creature_model_info display 11667 Gender 0; quest 13850 description and reward text; quest 13887 description and reward text (lighter colored shells; fewer with each clutch); quest 13906 description and reward text (baby teeth, few have the dedication)'),
(49017, 2, 490, 8, 0, 0, 'Blazerunner', 'Blazerunner is a great fire elemental who dwells on Fire Plume Ridge, the smoldering volcano in the charred center of Un''Goro Crater. Living blazes and scorching elementals walk the burned slopes around him, but he is far stronger than any of them, wrapped in a fiery aura of his own, and those who close with him on the rocky paths of the ridge are met with bursts of searing flame.', 'zone_areas area 537: Living Blaze, Scorching Elemental, Blazerunner 9376; smart_scripts 9376 (Blazerunner''s Aura on reset, Blast Wave within 10 yards); quest 4084 description (evil of the purest form, aura none can dispel); quest 4005 description and reward text (charred center, aura, pushed from the rocky paths; totem to fight Blazerunner); quest 3962 description and completion text (guards the Golden Flame, aura created using it); quest 3961 description; DB: 9376 faction 91, rank 1, area 537; factiontemplate_dbc 91'),
(49018, 3, 490, 1, 0, 0, 'It''s a Secret to Everybody', 'On the shore of a small pond in the Marshlands lies a wrecked raft. The pond seems far too small to have carried it, though a look at the trees around it suggests the water has not always stood at the same level. Whoever rode the raft is nowhere to be seen, and a little exploring in and around the water may turn up a clue to who it was. A few stray travelers have gathered at Marshal''s Refuge to the north, and one of them may know more.', 'quests 3844, 3845, 3908, 3909, 4041, 3912, 3913, 3914 (descriptions, request and reward texts); feralas.json 35714 (Miblon guards the evoroot) and 35713 (Gregan, no triggers)'),
(49019, 3, 490, 2, 0, 0, 'The Golden Flame', 'Linken has his sword back, but not his memory. He knows he came to Un''Goro for something important, and he wonders whether he let it slip when he first arrived, disoriented, at Marshal''s Refuge. The gnome J.D. Collie was very kind to him then, so he sends a helper to ask her in her cave at the refuge, with a warning to be careful: she is always messing with those crazy glowing crystals, and no one is quite sure what she is up to in there.', 'quests 3941, 3942, 4084, 4005, 3961, 3962 (descriptions, completion and reward texts); felwood.json 36119 (Eridan Bluewind, Un''Goro quests mentioned without triggers)'),
(49020, 3, 490, 3, 0, 0, 'Marshal Expeditions', 'Marshal Expeditions came to Un''Goro on what was meant to be its greatest venture and met disaster after disaster. The crater''s beasts overran its base camps in the southwest and the northeast, and the troupe fled for higher ground, leaving behind its food, its research equipment and even Williden Marshal''s journal, later found mangled in the wilds. At the refuge, the expedition clings on. Williden needs the crate of foodstuffs and some of the equipment back if anyone is to survive. His sister Hol''anyee wants a scraping from the walls of the Gorishi hatcheries, to learn why the silithid are in the crater at all. Spark Nilminer, the reluctant chief digger, is meant to bring back bones of long-dead stegodons and diemetradons from Terror Run, though privately he admits that bones from living ones will do.', 'quests 3881, 3882, 3883, 3884 (descriptions, completion and reward texts); npc_text 3094'),
(49021, 3, 490, 4, 0, 0, 'Crystals of Power', 'Power crystals of red, blue, yellow and green lie all over the crater, and most people ignore them. J.D. Collie does not. Certain they hold power, she experiments endlessly in her cave at Marshal''s Refuge, so far without success, and sends out collectors when her supply runs low. She has also heard rumors of mysterious pylons standing in the wilds, large and lined with crystals inside, one somewhere in the north, one in the east and one in the west. Call her gullible, she says, but she is sure the stories are true, and that the pylons have something to do with the crystals.', 'quests 4284, 4285, 4287, 4288, 4321 (descriptions and reward texts); quests 4381-4386 completion texts; npc_text 2810, 2834, 2836, 2837, 2933; zone_areas: pylons 164955 (538), 164957 (1942), 164956 (543)'),
(49022, 3, 490, 5, 0, 0, 'Torwa''s Trials', 'Torwa Pathfinder grants his respect only to those who prove themselves against the crater''s greatest beasts. The first test lies north among the great apes, whose pelts will clothe his tribe. The hardest is Lar''korwi, dominant male of the ravasaurs, whose name means sharp claw. Long ago Torwa''s brother took meat from one of its kills. The beast followed him for days, destroying everything he touched, and when he fled the crater it killed him not far from Torwa''s camp. To provoke Lar''korwi, a hunter must repeat the offense and steal meat from its freshest kill.', 'quests 4289, 4301, 4290, 4291, 4292 (descriptions, completion and reward texts); npc_text 2835 (taurahe, sharp claw)'),
(49023, 3, 490, 6, 0, 0, 'The Gorishi Hive Queen', 'Scholars in Darnassus and Orgrimmar suspect that the silithid draw their strength from Un''Goro Crater, and Alchemist Pestlezugg of Gadgetzan, who has already studied the bugs of Tanaris, thinks the idea worth testing. His research tells him the silithid are like bees: destroy a hive''s queen, and the rest should be thrown into disarray. To bring the queen out he means to brew a lure, and for that he needs samples of the native Un''Goro soil and a scent gland taken undamaged from the Gorishi of the Slithering Scar, which is easier said than done.', 'quests 4493, 4494 descriptions and reward texts (Gracina, Zilzibin; Pestlezugg: perhaps it is); quest 4496 description, completion and reward text; tanaris.json 44030 (Pestlezugg''s earlier study)'),
(49024, 3, 490, 7, 0, 0, 'The Bloodpetal Feud', 'Larion and Muigin set out together and ended up lost in Un''Goro, and each blames the other. Larion says he knew the way until Muigin insisted on a shortcut; Muigin says he warned Larion they were going the wrong way. Now they camp a few steps apart at Marshal''s Refuge, neither willing to speak first. Muigin has turned to mischief, sure that the wild bloodpetals of the crater could be trained to obey commands, if only he had samples to study. Larion, meanwhile, is plagued by plant pests night and day, and blames Muigin for every one of them.', 'quests 4141, 4142, 4143, 4144 (Muigin, Alliance) and 4145, 4147, 4146, 4148 (Larion, Horde): descriptions, completion and reward texts; quest 4502 description (Liv, apprentice to Marvon); npc_text 6741 (Larion: pests night and day); creature_text 9119');
INSERT INTO `mod_lore_codex_part` (`Entry`, `Part`, `MinState`, `MaxState`, `Body`, `Sources`) VALUES
(49000, 1, 13, 255, 'On the northern bluffs above Marshal''s Refuge stand a great stone terrace and a waygate, both tied to the titans. The waygate joins the crater to Sholazar Basin in far Northrend, and cultists of the Scourge now hold the terrace and the silent stone colossus that stands upon it.', 'zone_areas: Shaper''s Terrace 4382 (Death''s Hand Acolyte 28602, The Etymidian 28092) and Waygate 4381; quest 12547 description; warcraft.wiki.gg/wiki/Shaper''s_Terrace (added in 3.0.2); mod-individual-progression ipp_aware_npcs.sql (28602 npc_ipp_wotlk)'),
(49004, 1, 0, 255, 'The ridge keeps a treasure in one of its caves. There lies the Golden Flame, an artifact of power more vast than anything Linken has known, and dangerous in the hands of one with an evil heart. Blazerunner guards it, and it was with the Flame that he raised the aura that makes him all but invincible.', 'quest 3962 description, log text and completion text'),
(49005, 1, 0, 255, 'Krakle''s thermometer settled the question, or nearly. Its readings showed a clear link between the heat of the volcano and the warmth of the springs, though he means to check his equations. One puzzle leads to another: he points the curious to his friend Donova Snowden, who stays by hot springs in Winterspring with no volcano anywhere near them.', 'quest 974 reward text; quest 980 description (offered on the 974 turn-in)'),
(49005, 2, 0, 255, 'Simone is not what she seems. When someone who has seen through her disguise challenges her, she laughs at the foolish request and accepts. Then the smiling stroller becomes Simone the Seductress, a demon, and her little Precious turns into Precious the Devourer, a demon beast at her side. She will have the duel on her own terms: if others pile in, the pair simply vanish.', 'gossip_menu_option 5868 (I am not fooled by your disguise, temptress); creature_template 14533 Simone the Seductress and 14538 Precious the Devourer (type 3 demon, faction 90); broadcast_text 9759, 9760 (laughs at your foolish request; As you wish); npc_stave_of_ancients.cpp npc_simone (reveal after the challenge; unfair fight: both despawn)'),
(49007, 1, 0, 255, 'The hive has a heart of sorts. Alchemist Pestlezugg of Gadgetzan believes that a crystal in the hatcheries serves the Gorishi as a hive-wide attunement device, and that a lure set upon it will rouse the hive''s queen from hiding, though never without her guards.', 'quest 4507 description; gameobject 174792 Gorishi Silithid Crystal, 174793 Gorishi Hive Hatchery'),
(49008, 1, 13, 255, 'Mor''vek now trains venomhides as mounts. Their eggs lie in the ravasaur nests of the marsh, and he will sell one of the young beasts only to a rider patient enough to grow used to its poison first.', 'quests 13850, 13887, 13906 (patch 3.2.0) descriptions and reward texts; zone_areas area 1942: Venomhide Egg 195022, Young Venomhide Ravasaur 34158'),
(49009, 1, 13, 255, 'Herenn does not give up the overlook quietly. As he fights he curses those who come for him as fools: they have found the only being that could stand up to the armies of the Scourge, and he swears they will never bring the Etymidian back to Northrend.', 'creature_text 28601 (in combat); smart_scripts 28601; creature_loot_template 28601: Omega Rune 38708 (needed for 12547)'),
(49009, 2, 13, 255, 'With the Omega Rune set into the empty slot, the colossus stirs at last and speaks: Omega Rune deployed, activation successful. Whatever it was woken for lies beyond the waygate, in the far north.', 'quest 12547 description; creature_text 28092 (on 12547 reward)'),
(49010, 1, 0, 255, 'At last his memory returns. Linken came to Un''Goro to fight the fire elemental Blazerunner, keeper of the Golden Flame, and that fight was to end a long journey. Yet he says he is no longer the hero. The hero is whoever brought his memory back, who must now finish what he began, and he warns that it is no task to attempt alone.', 'quest 3962 description; quest 3961 description (a true warrior at heart)'),
(49010, 2, 0, 255, 'With Blazerunner beaten, Linken sends the Golden Flame back to his homeland, where it will be protected and never again used for evil. He is deeply grateful to the one who did it, for without that help, he says, he would still have no idea who he is.', 'quest 3962 reward text'),
(49011, 1, 0, 255, 'Her persistence pays off in the end. Once all three pylons have been found, J.D. works through her calculations and declares that she has finally figured it out. She sets down how the crystals and the pylons work in a manual, and gladly answers any question about them.', 'quest 4321 description and reward text; creature_text 9117 group 2 (I have finally figured it out); npc_text 2833 (gossip after 4321)'),
(49014, 1, 0, 255, 'A-Me 01 stands at the edge of the apes'' land, two huge dents in her shoulder and head and no power running through her. A panel on her back slides open on plain instructions: replace the mithril casing, then turn her off and on again.', 'quest 4243 reward text; quest 4244 description'),
(49014, 2, 0, 255, 'The old mithril casing had burnt out. With a new one in place and the switch flipped off and on, A-Me woke and picked her way home, murmuring that A-Me is good, and Karna welcomed her back, promising to see to all those dents.', 'quest 4244 reward text; creature_text 9623; quest 4245 reward text'),
(49015, 1, 0, 255, 'Spraggle''s fear eases a little once the frenzied pterrordax are thinned. She is still absolutely terrified of the beasts, she admits, but with fewer of them about she might feel safe enough to venture out of Marshal''s Refuge at last.', 'quest 4501 reward text'),
(49015, 2, 0, 255, 'Ringo is found on the slopes of Fire Plume Ridge, overcome by the heat and sure he is suffering from heat exhaustion. He thinks he can follow a guide back to the refuge, though he may faint again on the way, and a splash of water from Spraggle''s canteen should bring him round.', 'quest 4492 reward text; quest 4491 description; creature_text 9999'),
(49015, 3, 0, 255, 'Ringo made it back, soaked and unsteady but alive, and greeted Spraggle as one who had not expected to see her again. She has him home not in the best of shape, but in one piece, and is glad of whoever brought him.', 'quest 4491 reward text; creature_text 9999 group 3, 9997 group 0'),
(49016, 1, 13, 255, 'Mor''vek now sells venomhides as mounts to those who can earn one, and he warns every visitor that it takes a great deal of dedication to train and ride such a beast.', 'npc_text 14474 (gossip menu 10438, patch 3.2.0); warcraft.wiki.gg/wiki/Mor''vek (returned in 3.2.0)'),
(49016, 2, 13, 255, 'It is not a trade for the impatient. The beasts are poison through and through, in blood, spit and skin, and anyone who climbs onto one unprepared falls off dead within hours. He sells only to one who has built up a tolerance by being splashed with their poisoned blood again and again.', 'quest 13850 description and reward text'),
(49016, 3, 13, 255, 'A tolerance is only the start. The rider must find the rare light-shelled eggs in the marsh nests, which grow fewer with every clutch, and raise the hatchling under Mor''vek''s guidance, for venomhides are vicious and must be trained from the moment they hatch.', 'quest 13887 description and reward text'),
(49016, 4, 13, 255, 'The hatchling must be hand-fed until it has shed all its baby teeth. Then Mor''vek fits the saddle and trains it to answer a whistle. Few have the dedication to hand-feed and raise a venomhide, he says, but they are well worth the effort.', 'quest 13906 description and reward text; quests 13889, 13903, 13904, 13905, 13914-13917 (hatchling feeding)'),
(49017, 1, 0, 255, 'The druid Eridan Bluewind of the Emerald Circle names Blazerunner the purest evil. No one can dispel the aura that shields him, she warns, unless they hold power enough for the task, and she can teach how such power is gained.', 'quest 4084 description'),
(49017, 2, 0, 255, 'That power is the Silver Totem of Aquementas, forged by the summoned elemental Aquementas from claws and an irontree''s heart gathered in Felwood, and made to fight Blazerunner. J.D. Collie admits that everyone at the refuge gives him a wide berth: his aura has never been broken, and many who challenged him were thrown down from the ridge''s paths.', 'quest 4005 description and reward text; quest 3962 completion text (only the Silver Totem of Aquementas can remove it); smart_scripts 9376 (spellhit 14247 removes aura 13913)'),
(49017, 3, 0, 255, 'Blazerunner is more than a wild flame. In a cave on the ridge he keeps the Golden Flame, a relic of immense power, and it was by its power that he made the aura around him. The gnome Linken''s long journey was meant to end in a fight with him.', 'quest 3962 description and completion text; quest 3961 description'),
(49018, 1, 0, 255, 'At the bottom of the pond lies a water-logged pack, and its contents lead to Linken at Marshal''s Refuge, a gnome who finds them familiar, kind of. One memory stirs: his sword was meant to be strengthened, though he cannot say why. He sends it to Donova Snowden, who can temper it by the hot springs of Winterspring.', 'quest 3844 reward text; quest 3845 description and reward text; quest 3908 description'),
(49018, 2, 0, 255, 'Donova tempers the blade, and learns with alarm that Linken has lost his memory, for he is not usually one to forget things. The sword is still not complete. One being can finish it, but speaking with him will be difficult: it needs a Videre Elixir, and only Gregan Brewspewer, camped in the wilds of Feralas, knows how to make one.', 'quest 3908 completion and reward text; quest 3909 description'),
(49018, 3, 0, 255, 'Gregan brews the elixir from evoroot. Whoever drinks it in the graveyard outside Gadgetzan passes into another form, able to speak with one the living would not normally even see, and walks due north to the mountains, where Gaeriyan waits in one of the rocky crevices.', 'quest 4041 completion text (evoroot); quest 3909 reward text; quest 3912 description; feralas.json 35714 (Miblon guards the evoroot)'),
(49018, 4, 0, 255, 'Gaeriyan, who has had no visitor in a long time, tells of a gravestone in the graveyard unlike the others. Pushed firmly, it slides aside to reveal a small hollow that fits Linken''s sword perfectly, and when the blade is laid there it is transformed in a strong flash of light.', 'quest 3912 reward text; quest 3913 description and reward text; quest 3914 description'),
(49018, 5, 0, 255, 'Linken is delighted to have his sword back, finished at last, and he half remembers the one who brought it. Yet he still cannot remember why he needed it, and pays his helper for the work all the same.', 'quest 3914 completion and reward text'),
(49019, 1, 0, 255, 'J.D. remembers. Linken mumbled all kinds of strange things when he first arrived, likely after a hard bump on the head, but one stuck with her: he was making some sort of totem, and had to speak with someone named Eridan Bluewind in Felwood.', 'quest 3942 description'),
(49019, 2, 0, 255, 'Eridan does not know Linken, but she knows what he sought. In the heart of Un''Goro dwells an elemental called Blazerunner, evil of the purest form, behind an aura none can dispel save those with the power to do so. That power she can teach, in return for silvery claws and the heart of an irontree from the creatures of Felwood.', 'quest 4084 description'),
(49019, 3, 0, 255, 'For the claws and the heart, Eridan gives over the Book of Aquor, to be read from a circle of stones on the eastern point of Lost Rigger Cove in Tanaris. The elemental Aquementas is not pleased to be woken, but within the circle it forges the Silver Totem of Aquementas, and J.D. knows at once the elemental it was made to fight.', 'quest 4084 reward text; quest 4005 description, log text and reward text'),
(49019, 4, 0, 255, 'All this time, J.D. realizes, Linken came to rid them of Blazerunner. The totem brings back the last of his memory. This was to be the final step of his journey, yet he declares that the hero now is the one who helped him. Blazerunner guards the Golden Flame, a power vaster than any Linken has known, and it is dangerous to go alone.', 'quest 3961 description; quest 3962 description'),
(49019, 5, 0, 255, 'With the totem, Blazerunner''s aura is stripped away and the elemental falls. The Golden Flame is taken from its cave, and Linken sends it home to his homeland to be guarded, never again to be used for evil, and he thanks his helper warmly for giving him back his past.', 'quest 3962 log text, completion text and reward text'),
(49020, 1, 0, 255, 'The crate of foodstuffs and the research equipment came back, and with them the expedition''s hopes. Williden declares that the troupe has been saved, and its lives with it, and that they might now hold out in the crater for a while. Whoever brought the supplies home has a friend in Marshal Expeditions.', 'quest 3881 reward text'),
(49020, 2, 0, 255, 'Spark got his bones, and with them gave a loud, pointed speech of thanks for digging them all out of the ground without hurting the native beasts in any way. Whether that is true he does not want to know, and he hands over a little something to keep the matter quiet.', 'quest 3882 completion and reward text'),
(49020, 3, 0, 255, 'Hol''anyee has her sample of the hive wall, and the expedition''s research goes on. Stranded as she is in the middle of a savage land, she can give little in return, but she insists that none of the work done here would have been possible without the help she was given.', 'quest 3883 reward text'),
(49021, 1, 0, 255, 'The stories are true. Searchers find all three: the northern pylon close to the tar pits, the eastern in the Marshlands and the western near the Golakka springs. To the crater''s few residents they are a mystery and a source of legend, with much speculation about their purpose, and J.D. sets to work on her calculations.', 'quests 4285, 4287, 4288 reward texts; quest 4321 description (needs all three pylon quests); npc_text 2810; zone_areas: pylons 164955 (538), 164957 (1942), 164956 (543)'),
(49021, 2, 0, 255, 'From what is learned, J.D. works out how each pylon fuses two colors of crystal into one charm. One heals, one steadies the spirit, one hardens the body against blows, one weakens a foe''s defenses, one bursts in a stunning blast and one raises a shield that strikes back at attackers. She sets it all down in a manual for those who would use them.', 'quest 4321 reward text; npc_text 2834, 2836, 2837, 2933; quests 4381-4386'),
(49022, 1, 0, 255, 'The apes fall, and Torwa gives praise to the Earth Mother and thanks their spirits, though he calls the challenge small beside Lar''korwi. He has seen another test among the gorillas to the north: a huge ape in their cave that he calls U''cha, one of the Earth Mother''s greatest sons.', 'quest 4289 reward text; quest 4301 description'),
(49022, 2, 0, 255, 'U''cha was magnificent, huge and red, with teeth the size of daggers and arms as thick as tree trunks, a creature Torwa''s people might go generations without seeing. Whoever bests him earns Torwa''s word that the name of great hunter is deserved.', 'quest 4301 description, completion and reward text'),
(49022, 3, 0, 255, 'The freshest kill turns out to be a threshadon, an odd find in this part of the crater, and Torwa keeps the meat for the confrontation to come. His final plan needs the scent glands of Lar''korwi''s mates, taken where they guard their eggs west of his camp.', 'quest 4290 reward text; quest 4291 description (offered on the 4290 turn-in)'),
(49022, 4, 0, 255, 'Laid together on a small trail into the mountains, among the bones of massive creatures, the meat and the glands draw Lar''korwi into the open. His head brings Torwa''s highest praise: only the greatest of his ancestors, he says, could have done so much.', 'quest 4292 description and reward text'),
(49023, 1, 0, 255, 'With his special additions the lure is ready. Somewhere in the hive''s hatcheries, Pestlezugg believes, lies a crystal the silithid use as a hive-wide attunement device. The lure set upon it should roust out the Gorishi Hive Queen, though she will be protected by guards, and he wants her brain brought back for study, however icky that sounds.', 'quest 4496 reward text; quest 4507 description'),
(49023, 2, 0, 255, 'The Gorishi Hive Queen falls, and her brain reaches Gadgetzan. Pestlezugg had come to believe that the silithid might be controlled by a malign intelligence, and he shudders to think what could command creatures so insidious. Even in victory he is uneasy: so clean a resolution, he warns, cannot be the full extent of their presence.', 'quest 4507 completion and reward text; creature_loot_template 10041: Gorishi Queen Brain 11835'),
(49024, 1, 0, 255, 'Muigin found that the plants seem to have some small intelligence and sent one to his friend Gregan Brewspewer, an herbalist who left Ironforge for the quiet of the Feralas wilds and gets more visitors there than he ever did in the city. Gregan has never seen such plants, but he knows what will control them: Atal''ai haze from the sunken temple of Atal''Hakkar in the Swamp of Sorrows.', 'quest 4142 description and completion text; quest 4143 description'),
(49024, 2, 0, 255, 'Muigin admits he is vengeful. The haze goes into a heap of bloodpetal sprouts, plants not yet fully grown, and Muigin is sure the result will get Larion''s attention. He even confesses that he knows the way home, but he will not leave until Larion admits that Muigin was right.', 'quest 4144 completion and reward text'),
(49024, 3, 0, 255, 'Larion spied on Muigin and caught him growing the pests, and he means to fight back rather than talk. His friend Marvon Rivetseeker of Ratchet is away studying the troll ruins of Tanaris, but Marvon''s apprentice Liv Rizzlefix has built a short range bug zapper, fueled by Atal''ai haze from the sunken temple of Atal''Hakkar.', 'quest 4147 description and reward text; quest 4146 description; quest 4502 description (Liv, apprentice to Marvon)'),
(49024, 4, 0, 255, 'Calibrated with a bloodpetal sprout, the zapper is ready for Muigin''s little friends. Larion insists the prank does not bother him at all, though he grumbles that if Muigin were not so stubborn, the two of them could already be on their way home.', 'quest 4148 completion and reward text');
